template<class ReadWord> constexpr const Game* select(std::size_t textSize, ReadWord readWord) {
    const Game* selected = nullptr;
    for (const auto& game : kGames) {
        bool matched = true;
        for (const auto& site : game.identity)
            if (site.offset < 0 || static_cast<std::size_t>(site.offset) + 4 > textSize ||
                readWord(site.offset) != site.word) { matched = false; break; }
        if (!matched) continue;
        if (selected) return nullptr;
        selected = &game;
    }
    return selected;
}
